"""Anbindung an den Paketdienst und Versandtarife (siehe interfaces.RateProvider)."""

from __future__ import annotations

import itertools
from dataclasses import dataclass

from lagerwerk.config import MAX_PARCEL_WEIGHT_G, ZONES
from lagerwerk.models import Label, Parcel
from lagerwerk.money import cents_from_str, gross_cents


class CarrierError(RuntimeError):
    """Oberklasse aller Fehler des Paketdienstes."""


class CarrierUnavailable(CarrierError):
    """Vorübergehend: Zeitüberschreitung, Wartung, 503. Ein neuer Versuch kann gelingen."""


class CarrierRejected(CarrierError):
    """Endgültig: Das Paket wird so nicht angenommen (Gewicht, Zone, Gefahrgut)."""


@dataclass(frozen=True)
class BookingRequest:
    order_id: str
    zone: str
    weight_g: int
    price_cents: int
    hazardous: bool = False


class FakeCarrier:
    """Paketdienst für Tests und den Probebetrieb.

    `outages` ist die Zahl der nächsten Aufrufe, die mit CarrierUnavailable scheitern.
    Geprüft wird wie beim echten Dienst: Zone, Gewicht (exklusive Grenze, siehe config),
    Gefahrgut nur in Zone DE.
    """

    name = "DPX"

    def __init__(self, outages: int = 0):
        self.outages = outages
        self.booked: dict[str, BookingRequest] = {}
        self.cancelled: list[str] = []
        self._numbers = itertools.count(1)
        self.calls = 0

    def book(self, request: BookingRequest) -> Label:
        self.calls += 1
        if self.outages > 0:
            self.outages -= 1
            raise CarrierUnavailable("Dienst nicht erreichbar")
        if request.zone not in ZONES:
            raise CarrierRejected(f"Zone {request.zone} nicht im Vertrag")
        if request.weight_g >= MAX_PARCEL_WEIGHT_G:
            raise CarrierRejected(f"{request.weight_g} g über Höchstgewicht")
        if request.hazardous and request.zone != "DE":
            raise CarrierRejected("Gefahrgut nur innerhalb DE")
        tracking = f"{self.name}{next(self._numbers):08d}"
        self.booked[tracking] = request
        return Label(tracking, self.name, request.price_cents)

    def cancel(self, tracking_no: str) -> None:
        if tracking_no not in self.booked:
            raise CarrierRejected(f"{tracking_no} unbekannt")
        del self.booked[tracking_no]
        self.cancelled.append(tracking_no)


class FlatRateProvider:
    """Ein Preis für alles; der Vertrag nennt ihn netto."""

    def __init__(self, net_price: str):
        self.net_cents = cents_from_str(net_price)

    def quote(self, parcel: Parcel) -> int:
        return gross_cents(self.net_cents)


class WeightRateProvider:
    """Preis nach Gewichtsstufen in kg, netto aus dem Vertrag.

    `steps` ist eine Liste (bis_kg, netto) aufsteigend; das letzte bis_kg gilt nach oben
    offen.
    """

    def __init__(self, steps: list[tuple[int, str]]):
        if not steps:
            raise ValueError("mindestens eine Gewichtsstufe")
        self.steps = [(limit, cents_from_str(price)) for limit, price in steps]
        if [s[0] for s in self.steps] != sorted(s[0] for s in self.steps):
            raise ValueError("Gewichtsstufen müssen aufsteigend sein")

    def net_for(self, weight_g: int) -> int:
        for limit_kg, net in self.steps:
            if weight_g <= limit_kg * 1000:
                return net
        return self.steps[-1][1]

    def quote(self, parcel: Parcel) -> int:
        return gross_cents(self.net_for(parcel.weight_g))

