"""Artikelstamm."""

from __future__ import annotations

import json
from pathlib import Path

from lagerwerk.models import Article


class UnknownArticle(KeyError):
    """Die SKU steht nicht im Katalog."""


class Catalog:
    def __init__(self, articles: list[Article] | None = None):
        self._articles: dict[str, Article] = {}
        self._discontinued: set[str] = set()
        for article in articles or []:
            self.add(article)

    def add(self, article: Article) -> None:
        if article.sku in self._articles:
            raise ValueError(f"{article.sku} ist schon im Katalog")
        self._articles[article.sku] = article

    def get(self, sku: str) -> Article:
        """Liefert den Artikel; unbekannte SKU wirft UnknownArticle."""
        try:
            return self._articles[sku]
        except KeyError:
            raise UnknownArticle(sku) from None

    def __contains__(self, sku: str) -> bool:
        return sku in self._articles

    def __len__(self) -> int:
        return len(self._articles)

    def weight_of(self, sku: str, qty: int = 1) -> int:
        return self.get(sku).weight_g * qty

    def discontinue(self, sku: str) -> None:
        self.get(sku)
        self._discontinued.add(sku)

    def is_active(self, sku: str) -> bool:
        return sku in self._articles and sku not in self._discontinued

    def active(self) -> list[Article]:
        return sorted(
            (a for a in self._articles.values() if a.sku not in self._discontinued),
            key=lambda a: a.sku,
        )

    def hazardous(self) -> list[str]:
        return sorted(a.sku for a in self._articles.values() if a.hazardous)

    def search(self, text: str) -> list[Article]:
        needle = text.casefold()
        return [a for a in self.active() if needle in a.name.casefold() or needle in a.sku.casefold()]

    @classmethod
    def load(cls, path: Path) -> "Catalog":
        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        catalog = cls()
        for entry in raw["articles"]:
            catalog.add(Article(entry["sku"], entry["name"], int(entry["weight_g"]), bool(entry.get("hazardous"))))
        for sku in raw.get("discontinued", []):
            catalog.discontinue(sku)
        return catalog

    def dump(self) -> dict:
        return {
            "articles": [
                {"sku": a.sku, "name": a.name, "weight_g": a.weight_g, "hazardous": a.hazardous}
                for a in sorted(self._articles.values(), key=lambda a: a.sku)
            ],
            "discontinued": sorted(self._discontinued),
        }

