"""Versand eines Auftrags: Pakete buchen, bei Fehlern wiederholen oder zurückrollen."""

from __future__ import annotations

import logging
import time

from lagerwerk.carrier import CarrierError, CarrierUnavailable
from lagerwerk.config import CARRIER_ATTEMPTS, CARRIER_BACKOFF_S
from lagerwerk.interfaces import Booker
from lagerwerk.models import Label, Order, Parcel
from lagerwerk.reservations import ReservationBook

log = logging.getLogger(__name__)


class DispatchFailed(CarrierError):
    """Ein Auftrag konnte nicht versandt werden; alles Gebuchte ist storniert."""

    def __init__(self, order_id: str, cause: CarrierError):
        super().__init__(f"{order_id}: {cause}")
        self.order_id = order_id
        self.cause = cause


class Dispatcher:
    """Bucht die Pakete eines Auftrags über einen Booker.

    Ein Auftrag geht ganz oder gar nicht raus. Wirft der Booker CarrierUnavailable, wird
    bis zu CARRIER_ATTEMPTS-mal mit Wartezeit wiederholt. Bleibt es dabei oder wirft er
    CarrierRejected, storniert ship() die schon gebuchten Pakete des Auftrags, gibt die
    Reservierung frei und wirft DispatchFailed. Nur wenn jedes Paket ein Label hat, wird
    die Reservierung bestätigt.
    """

    def __init__(self, carrier, reservations: ReservationBook, sleep=time.sleep):
        self.carrier = carrier
        self.reservations = reservations
        self.sleep = sleep
        self.attempts_used = 0

    def ship(self, order: Order, parcels: list[Parcel], booker: Booker) -> list[Label]:
        labels: list[Label] = []
        try:
            for parcel in parcels:
                labels.append(self._book_with_retry(booker, parcel))
        except CarrierError as exc:
            self._roll_back(order, labels)
            raise DispatchFailed(order.order_id, exc) from exc
        self.reservations.confirm(order.order_id)
        return labels

    def _book_with_retry(self, booker: Booker, parcel: Parcel) -> Label:
        for attempt in range(1, CARRIER_ATTEMPTS + 1):
            self.attempts_used += 1
            try:
                return booker.book(parcel)
            except CarrierUnavailable:
                if attempt == CARRIER_ATTEMPTS:
                    raise
                log.info("Paketdienst nicht erreichbar, Versuch %d von %d", attempt, CARRIER_ATTEMPTS)
                self.sleep(CARRIER_BACKOFF_S * attempt)
        raise AssertionError("unerreichbar")

    def _roll_back(self, order: Order, labels: list[Label]) -> None:
        for label in labels:
            try:
                self.carrier.cancel(label.tracking_no)
            except CarrierError:
                log.error("Storno von %s fehlgeschlagen, bitte von Hand prüfen", label.tracking_no)
        self.reservations.release(order.order_id)

