"""Wareneingang: Lieferavis abgleichen, einlagern; Retouren prüfen und zurückbuchen."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum

from lagerwerk.catalog import Catalog, UnknownArticle
from lagerwerk.config import AISLES, SHELVES_PER_AISLE
from lagerwerk.models import Bin
from lagerwerk.warehouse import Warehouse


@dataclass
class AdviceLine:
    sku: str
    qty: int


@dataclass
class Delivery:
    delivery_id: str
    supplier: str
    advised: list[AdviceLine]
    received: dict[str, int] = field(default_factory=dict)

    def count(self, sku: str, qty: int) -> None:
        if qty < 0:
            raise ValueError("gezählte Menge darf nicht negativ sein")
        self.received[sku] = self.received.get(sku, 0) + qty


@dataclass
class Discrepancy:
    sku: str
    advised: int
    received: int

    @property
    def difference(self) -> int:
        return self.received - self.advised

    def describe(self) -> str:
        sign = "+" if self.difference > 0 else ""
        return f"{self.sku}: avisiert {self.advised}, gezählt {self.received} ({sign}{self.difference})"


def compare(delivery: Delivery) -> list[Discrepancy]:
    """Abweichungen zwischen Avis und Zählung, auch für nicht avisierte Artikel."""
    advised: dict[str, int] = {}
    for line in delivery.advised:
        advised[line.sku] = advised.get(line.sku, 0) + line.qty
    result = []
    for sku in sorted(set(advised) | set(delivery.received)):
        a, r = advised.get(sku, 0), delivery.received.get(sku, 0)
        if a != r:
            result.append(Discrepancy(sku, a, r))
    return result


class PutAwayPlanner:
    """Schlägt Einlagerplätze vor.

    Schnelldreher (die `fast_movers`) kommen in die ersten drei Gänge, alles andere von
    hinten nach vorn. Ein Fach, in dem schon dieselbe SKU liegt, hat Vorrang.
    """

    FAST_AISLES = 3

    def __init__(self, warehouse: Warehouse, fast_movers: set[str] | None = None):
        self.warehouse = warehouse
        self.fast_movers = fast_movers or set()
        self._occupied: set[Bin] = set()

    def mark_occupied(self, bin_: Bin) -> None:
        self._occupied.add(bin_)

    def suggest(self, sku: str) -> Bin:
        existing = self.warehouse.bins_for(sku)
        if existing:
            return existing[0][0]
        if sku in self.fast_movers:
            aisles = range(1, self.FAST_AISLES + 1)
        else:
            aisles = range(AISLES, self.FAST_AISLES, -1)
        for aisle in aisles:
            for shelf in range(1, SHELVES_PER_AISLE + 1):
                candidate = Bin(aisle, shelf)
                if candidate not in self._occupied:
                    self._occupied.add(candidate)
                    return candidate
        raise RuntimeError("kein freies Fach")


@dataclass
class ReceiptResult:
    stored: list[tuple[str, Bin, int]]
    rejected: list[str]
    discrepancies: list[Discrepancy]


def receive(delivery: Delivery, catalog: Catalog, warehouse: Warehouse, planner: PutAwayPlanner) -> ReceiptResult:
    """Lagert alles Gezählte ein. Unbekannte oder ausgelistete SKUs werden abgelehnt."""
    stored, rejected = [], []
    for sku, qty in sorted(delivery.received.items()):
        if qty == 0:
            continue
        try:
            catalog.get(sku)
        except UnknownArticle:
            rejected.append(sku)
            continue
        if not catalog.is_active(sku):
            rejected.append(sku)
            continue
        bin_ = planner.suggest(sku)
        warehouse.put(sku, bin_, qty)
        stored.append((sku, bin_, qty))
    return ReceiptResult(stored, rejected, compare(delivery))


class Condition(Enum):
    NEW = "neu"
    OPENED = "geöffnet"
    DAMAGED = "beschädigt"
    MISSING_PARTS = "unvollständig"


#: Zustände, in denen eine Retoure wieder verkauft werden darf.
RESELLABLE = {Condition.NEW, Condition.OPENED}


@dataclass
class ReturnItem:
    rma: str
    order_id: str
    sku: str
    qty: int
    condition: Condition
    note: str = ""


@dataclass
class ReturnDecision:
    item: ReturnItem
    bin: Bin
    restocked: bool
    reason: str


class ReturnDesk:
    """Bucht Retouren. Verkaufbare Ware geht zurück ins Fach, der Rest ins Sperrlager.

    Gefahrgut wird nie direkt zurückgelagert, auch neuwertig nicht: Es geht ins
    Sperrlager, bis die Fachkraft es freigibt (Warehouse.release_quarantine).
    """

    def __init__(self, warehouse: Warehouse, catalog: Catalog, return_bin: Bin):
        self.warehouse = warehouse
        self.catalog = catalog
        self.return_bin = return_bin
        self.log: list[ReturnDecision] = []

    def book(self, item: ReturnItem) -> ReturnDecision:
        article = self.catalog.get(item.sku)
        if item.qty <= 0:
            raise ValueError(f"{item.rma}: Menge muss positiv sein")
        if article.hazardous:
            decision = self._quarantine(item, "Gefahrgut, Freigabe durch Fachkraft")
        elif item.condition in RESELLABLE and self.catalog.is_active(item.sku):
            target = self._restock_bin(item.sku)
            self.warehouse.put(item.sku, target, item.qty)
            decision = ReturnDecision(item, target, True, "wieder eingelagert")
        elif item.condition in RESELLABLE:
            decision = self._quarantine(item, "Artikel ausgelistet")
        else:
            decision = self._quarantine(item, f"Zustand: {item.condition.value}")
        self.log.append(decision)
        return decision

    def _restock_bin(self, sku: str) -> Bin:
        bins = self.warehouse.bins_for(sku)
        return bins[0][0] if bins else self.return_bin

    def _quarantine(self, item: ReturnItem, reason: str) -> ReturnDecision:
        self.warehouse.put(item.sku, self.return_bin, item.qty)
        self.warehouse.to_quarantine(item.sku, self.return_bin, item.qty)
        return ReturnDecision(item, self.return_bin, False, reason)

    def summary(self) -> dict[str, int]:
        result = {"wieder eingelagert": 0, "Sperrlager": 0}
        for decision in self.log:
            result["wieder eingelagert" if decision.restocked else "Sperrlager"] += decision.item.qty
        return result

