"""Schnittstellen zwischen den Bausteinen des Versands.

Implementierungen halten sich an die Docstrings hier; die Aufrufer prüfen die
zugesicherten Eigenschaften nicht noch einmal.
"""

from __future__ import annotations

from typing import Protocol

from lagerwerk.models import Label, Parcel, PickStop


class Booker(Protocol):
    def book(self, parcel: Parcel) -> Label:
        """Bucht ein Paket beim Paketdienst und liefert dessen Label.

        Fehler des Paketdienstes werden nicht behandelt, sondern als CarrierError
        weitergereicht: Wiederholung bei CarrierUnavailable und Storno samt Freigabe der
        Reservierung erledigt Dispatcher.ship.
        """


class RateProvider(Protocol):
    def quote(self, parcel: Parcel) -> int:
        """Versandpreis des Pakets in Cent, brutto (inklusive VAT_PERCENT Mehrwertsteuer).

        Der Wert landet unverändert auf Label und Rechnung; niemand rechnet ihn später
        noch einmal um.
        """


class PickingStrategy(Protocol):
    def route(self, stops: list[PickStop]) -> list[PickStop]:
        """Ordnet die Halte in Laufreihenfolge. Jeder Halt hat ein Fach."""


class ExportTarget(Protocol):
    def write_row(self, row: list[str]) -> None:
        """Schreibt eine Zeile."""

    def commit(self) -> int:
        """Schließt das Ziel ab und liefert die Zahl der Zeilen."""

