"""Datenklassen des Lagers."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime

from lagerwerk.config import AISLES, CARTON_TARE_G, SHELVES_PER_AISLE


@dataclass(frozen=True)
class Article:
    sku: str
    name: str
    weight_g: int
    hazardous: bool = False

    def __post_init__(self):
        if self.weight_g <= 0:
            raise ValueError(f"{self.sku}: Gewicht muss positiv sein")


@dataclass(frozen=True, order=True)
class Bin:
    """Lagerfach. Sortierung nach Gang, dann Fach, dann Ebene ergibt die Laufreihenfolge."""

    aisle: int
    shelf: int
    level: int = 0

    def __post_init__(self):
        if not 1 <= self.aisle <= AISLES:
            raise ValueError(f"Gang {self.aisle} existiert nicht")
        if not 1 <= self.shelf <= SHELVES_PER_AISLE:
            raise ValueError(f"Fach {self.shelf} existiert nicht")

    @property
    def label(self) -> str:
        return f"G{self.aisle:02d}-F{self.shelf:02d}-E{self.level}"

    @classmethod
    def parse(cls, text: str) -> "Bin":
        aisle, shelf, level = text.split("-")
        return cls(int(aisle[1:]), int(shelf[1:]), int(level[1:]))


@dataclass
class OrderLine:
    sku: str
    qty: int

    def __post_init__(self):
        if self.qty <= 0:
            raise ValueError(f"{self.sku}: Menge muss positiv sein")


@dataclass
class Order:
    order_id: str
    customer_id: str
    lines: list[OrderLine]
    zone: str = "DE"
    created: datetime | None = None

    def total_qty(self) -> int:
        return sum(line.qty for line in self.lines)

    def skus(self) -> list[str]:
        return [line.sku for line in self.lines]


@dataclass
class Label:
    tracking_no: str
    carrier: str
    price_cents: int


@dataclass
class Parcel:
    order_id: str
    zone: str = "DE"
    contents: list[OrderLine] = field(default_factory=list)
    weight_g: int = CARTON_TARE_G
    price_cents: int | None = None
    label: Label | None = None

    def add(self, sku: str, qty: int, unit_weight_g: int) -> None:
        for line in self.contents:
            if line.sku == sku:
                line.qty += qty
                break
        else:
            self.contents.append(OrderLine(sku, qty))
        self.weight_g += qty * unit_weight_g

    def is_empty(self) -> bool:
        return not self.contents


@dataclass
class PickStop:
    """Ein Halt auf der Kommissionierrunde."""

    bin: Bin
    sku: str
    qty: int
    order_id: str

