"""Geldbeträge. Intern immer ganze Cent, gerundet wird kaufmännisch."""

from __future__ import annotations

from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from lagerwerk.config import VAT_PERCENT


def cents_from_str(text: str) -> int:
    """'12,90' oder '12.90' -> 1290. Leerer Text ist 0."""
    text = text.strip().replace(" ", "")
    if not text:
        return 0
    if "," in text:
        text = text.replace(".", "").replace(",", ".")
    try:
        value = Decimal(text)
    except InvalidOperation as exc:
        raise ValueError(f"kein Betrag: {text!r}") from exc
    return int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def gross_cents(net_cents: int, vat_percent: int = VAT_PERCENT) -> int:
    """Nettobetrag in Cent -> Bruttobetrag in Cent."""
    gross = Decimal(net_cents) * (100 + vat_percent) / 100
    return int(gross.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def net_cents(gross: int, vat_percent: int = VAT_PERCENT) -> int:
    """Bruttobetrag in Cent -> Nettobetrag in Cent."""
    net = Decimal(gross) * 100 / (100 + vat_percent)
    return int(net.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def format_eur(cents: int) -> str:
    """1290 -> '12,90 €', -5 -> '-0,05 €'."""
    sign = "-" if cents < 0 else ""
    euros, rest = divmod(abs(cents), 100)
    grouped = f"{euros:,}".replace(",", ".")
    return f"{sign}{grouped},{rest:02d} €"


def split_evenly(total_cents: int, parts: int) -> list[int]:
    """Verteilt einen Betrag auf n Teile; die ersten Teile bekommen den Rest-Cent."""
    if parts <= 0:
        raise ValueError("parts muss positiv sein")
    base, rest = divmod(total_cents, parts)
    return [base + (1 if i < rest else 0) for i in range(parts)]

