"""Auswertungen für Schichtleitung und Buchhaltung."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass

from lagerwerk.catalog import Catalog
from lagerwerk.models import Label, Order
from lagerwerk.money import format_eur, net_cents
from lagerwerk.warehouse import Warehouse


@dataclass
class ShippingTotals:
    parcels: int
    gross_cents: int

    @property
    def net_cents(self) -> int:
        return net_cents(self.gross_cents)

    def lines(self) -> list[str]:
        return [
            f"Pakete: {self.parcels}",
            f"Versandkosten brutto: {format_eur(self.gross_cents)}",
            f"Versandkosten netto: {format_eur(self.net_cents)}",
        ]


def shipping_totals(labels: list[Label]) -> ShippingTotals:
    """Summe über Labels; Label.price_cents ist brutto (siehe interfaces.RateProvider)."""
    return ShippingTotals(len(labels), sum(label.price_cents for label in labels))


def low_stock_report(warehouse: Warehouse, catalog: Catalog) -> list[str]:
    rows = warehouse.low_stock([a.sku for a in catalog.active()])
    if not rows:
        return ["Kein Artikel knapp."]
    return [f"{sku} {catalog.get(sku).name}: {qty} Stück" for sku, qty in rows]


def top_articles(orders: list[Order], limit: int = 10) -> list[tuple[str, int]]:
    counter: Counter[str] = Counter()
    for order in orders:
        for line in order.lines:
            counter[line.sku] += line.qty
    return sorted(counter.items(), key=lambda item: (-item[1], item[0]))[:limit]


def zone_mix(orders: list[Order]) -> dict[str, int]:
    return dict(sorted(Counter(order.zone for order in orders).items()))


def locked_bins_report(warehouse: Warehouse) -> list[str]:
    bins = warehouse.locked_bins()
    if not bins:
        return ["Keine Inventursperre."]
    return [f"Gesperrt: {bin_.label}" for bin_ in bins]

