"""Reservierungen gegen den verfügbaren Bestand."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta

from lagerwerk.config import RESERVATION_TTL_MIN
from lagerwerk.models import Order
from lagerwerk.warehouse import Warehouse


class InsufficientStock(RuntimeError):
    def __init__(self, sku: str, wanted: int, free: int):
        super().__init__(f"{sku}: {wanted} verlangt, {free} frei")
        self.sku, self.wanted, self.free = sku, wanted, free


@dataclass
class Reservation:
    order_id: str
    quantities: dict[str, int]
    created: datetime
    confirmed: bool = False

    def expires(self) -> datetime:
        return self.created + timedelta(minutes=RESERVATION_TTL_MIN)


class ReservationBook:
    """Hält, was für offene Aufträge zurückgelegt ist.

    Ablauf je Auftrag: reserve() vor dem Packen, confirm() nach erfolgreichem Versand,
    release() wenn der Versand scheitert. Nicht bestätigte Reservierungen verfallen über
    expire().
    """

    def __init__(self, warehouse: Warehouse, clock=datetime.now):
        self.warehouse = warehouse
        self.clock = clock
        self._open: dict[str, Reservation] = {}

    def reserved(self, sku: str) -> int:
        return sum(r.quantities.get(sku, 0) for r in self._open.values())

    def free(self, sku: str) -> int:
        return self.warehouse.available(sku) - self.reserved(sku)

    def reserve(self, order: Order) -> Reservation:
        if order.order_id in self._open:
            raise ValueError(f"{order.order_id} ist schon reserviert")
        wanted: dict[str, int] = {}
        for line in order.lines:
            wanted[line.sku] = wanted.get(line.sku, 0) + line.qty
        for sku, qty in wanted.items():
            free = self.free(sku)
            if qty > free:
                raise InsufficientStock(sku, qty, free)
        reservation = Reservation(order.order_id, wanted, self.clock())
        self._open[order.order_id] = reservation
        return reservation

    def confirm(self, order_id: str) -> Reservation:
        reservation = self._open.pop(order_id)
        reservation.confirmed = True
        return reservation

    def release(self, order_id: str) -> Reservation | None:
        return self._open.pop(order_id, None)

    def is_open(self, order_id: str) -> bool:
        return order_id in self._open

    def expire(self) -> list[str]:
        now = self.clock()
        gone = [oid for oid, r in self._open.items() if r.expires() <= now]
        for oid in gone:
            del self._open[oid]
        return gone

    def open_orders(self) -> list[str]:
        return sorted(self._open)

