"""Dateien: Exporte als CSV, Zustände als JSON."""

from __future__ import annotations

import csv
import json
import os
from pathlib import Path


class ExportSink:
    """CSV-Export, der nie halb fertig am Zielort liegt.

    open() legt `<ziel>.part` an und hält den Dateihandle offen; commit() schließt ihn und
    benennt die Datei auf das Ziel um. Scheitert etwas dazwischen, muss der Aufrufer
    discard() rufen: Erst das schließt den Handle und löscht die .part-Datei. Am
    einfachsten über `with ExportSink(...) as sink:`, dann ruft __exit__ bei einer
    Exception discard() und sonst commit().
    """

    def __init__(self, target: Path, header: list[str], delimiter: str = ";"):
        self.target = Path(target)
        self.part = self.target.with_name(self.target.name + ".part")
        self.header = header
        self.delimiter = delimiter
        self.rows = 0
        self._handle = None
        self._writer = None
        self._done = False

    def open(self) -> "ExportSink":
        self.target.parent.mkdir(parents=True, exist_ok=True)
        self._handle = self.part.open("w", encoding="utf-8", newline="")
        self._writer = csv.writer(self._handle, delimiter=self.delimiter)
        self._writer.writerow(self.header)
        return self

    def write_row(self, row: list) -> None:
        if self._writer is None:
            raise RuntimeError("ExportSink ist nicht geöffnet")
        if len(row) != len(self.header):
            raise ValueError(f"Zeile hat {len(row)} Felder, Kopf hat {len(self.header)}")
        self._writer.writerow(["" if value is None else str(value) for value in row])
        self.rows += 1

    def commit(self) -> int:
        if self._done:
            return self.rows
        self._handle.close()
        os.replace(self.part, self.target)
        self._done = True
        return self.rows

    def discard(self) -> None:
        if self._done:
            return
        if self._handle is not None:
            self._handle.close()
        self.part.unlink(missing_ok=True)
        self._done = True

    @property
    def closed(self) -> bool:
        return self._handle is None or self._handle.closed

    def __enter__(self) -> "ExportSink":
        return self.open()

    def __exit__(self, exc_type, exc, tb) -> bool:
        if exc_type is None:
            self.commit()
        else:
            self.discard()
        return False


def read_csv(path: Path, delimiter: str = ";") -> list[dict[str, str]]:
    with Path(path).open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle, delimiter=delimiter))


class JsonState:
    """Kleiner Zustandsspeicher; schreibt über eine Temp-Datei, damit nie halbe Dateien liegen."""

    def __init__(self, path: Path):
        self.path = Path(path)

    def load(self, default=None):
        if not self.path.exists():
            return default
        return json.loads(self.path.read_text(encoding="utf-8"))

    def save(self, data) -> None:
        text = json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True)
        tmp = self.path.with_name(self.path.name + ".tmp")
        tmp.write_text(text, encoding="utf-8")
        os.replace(tmp, self.path)

