"""Bestand je Fach, Sperrlager, Inventur und Laufreihenfolge."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field

from lagerwerk.config import LOW_STOCK_THRESHOLD
from lagerwerk.models import Bin, PickStop


class StockError(RuntimeError):
    """Bestandsbewegung nicht möglich."""


class Warehouse:
    """Bestand je (SKU, Fach).

    Zwei Zustände nehmen Bestand aus der Kommissionierung, aber nur einer aus dem
    Verkauf: Ware im Sperrlager (Quarantäne) ist weder verfügbar noch greifbar. Ein Fach
    unter Inventursperre bleibt verkaufbar (`available` zählt es mit), darf aber bis zur
    Freigabe nicht angefahren werden.
    """

    def __init__(self):
        self._stock: dict[str, dict[Bin, int]] = defaultdict(dict)
        self._quarantine: dict[str, dict[Bin, int]] = defaultdict(dict)
        self._locked: set[Bin] = set()

    # -- Bewegungen ---------------------------------------------------------------

    def put(self, sku: str, bin_: Bin, qty: int) -> None:
        if qty <= 0:
            raise StockError("Einlagerung braucht eine positive Menge")
        self._stock[sku][bin_] = self._stock[sku].get(bin_, 0) + qty

    def take(self, sku: str, bin_: Bin, qty: int) -> None:
        if bin_ in self._locked:
            raise StockError(f"{bin_.label} ist für die Inventur gesperrt")
        have = self._stock[sku].get(bin_, 0)
        if qty > have:
            raise StockError(f"{sku} in {bin_.label}: {have} vorhanden, {qty} verlangt")
        if qty == have:
            del self._stock[sku][bin_]
        else:
            self._stock[sku][bin_] = have - qty

    def move(self, sku: str, source: Bin, target: Bin, qty: int) -> None:
        self.take(sku, source, qty)
        self.put(sku, target, qty)

    def to_quarantine(self, sku: str, bin_: Bin, qty: int) -> None:
        self.take(sku, bin_, qty)
        self._quarantine[sku][bin_] = self._quarantine[sku].get(bin_, 0) + qty

    def release_quarantine(self, sku: str, bin_: Bin) -> int:
        qty = self._quarantine[sku].pop(bin_, 0)
        if qty:
            self.put(sku, bin_, qty)
        return qty

    # -- Inventur -----------------------------------------------------------------

    def lock(self, bin_: Bin) -> None:
        self._locked.add(bin_)

    def unlock(self, bin_: Bin) -> None:
        self._locked.discard(bin_)

    def locked_bins(self) -> list[Bin]:
        return sorted(self._locked)

    # -- Abfragen -----------------------------------------------------------------

    def available(self, sku: str) -> int:
        """Verkaufbarer Bestand: alles außer Sperrlager, Inventursperren eingeschlossen."""
        return sum(self._stock[sku].values())

    def quarantined(self, sku: str) -> int:
        return sum(self._quarantine[sku].values())

    def bins_for(self, sku: str) -> list[tuple[Bin, int]]:
        return sorted(self._stock[sku].items())

    def primary_bin(self, sku: str) -> Bin | None:
        """Fach, aus dem kommissioniert wird: das greifbare Fach mit dem größten Bestand,
        bei Gleichstand das näher am Packtisch.

        Greifbar heißt: nicht im Sperrlager und nicht unter Inventursperre. Liegt der
        ganze Bestand in gesperrten Fächern, gibt es heute kein Kommissionierfach, obwohl
        `available` > 0 ist; dann ist das Ergebnis None.
        """
        candidates = [(qty, bin_) for bin_, qty in self._stock[sku].items() if bin_ not in self._locked]
        if not candidates:
            return None
        best_qty = max(qty for qty, _ in candidates)
        return min(bin_ for qty, bin_ in candidates if qty == best_qty)

    def low_stock(self, skus: list[str]) -> list[tuple[str, int]]:
        return [(sku, self.available(sku)) for sku in skus if self.available(sku) <= LOW_STOCK_THRESHOLD]

    def snapshot(self) -> dict[str, dict[str, int]]:
        return {
            sku: {bin_.label: qty for bin_, qty in sorted(bins.items())}
            for sku, bins in sorted(self._stock.items())
            if bins
        }


class AisleStrategy:
    """Laufreihenfolge: Gang aufsteigend, in geraden Gängen Fächer absteigend (S-Kurve)."""

    def route(self, stops: list[PickStop]) -> list[PickStop]:
        def key(stop: PickStop):
            shelf = -stop.bin.shelf if stop.bin.aisle % 2 == 0 else stop.bin.shelf
            return (stop.bin.aisle, shelf, stop.bin.level, stop.sku)

        return sorted(stops, key=key)

    def merge(self, stops: list[PickStop]) -> list[PickStop]:
        """Fasst Halte am selben Fach für denselben Auftrag zusammen."""
        merged: dict[tuple, PickStop] = {}
        for stop in stops:
            key = (stop.bin, stop.sku, stop.order_id)
            if key in merged:
                merged[key].qty += stop.qty
            else:
                merged[key] = PickStop(stop.bin, stop.sku, stop.qty, stop.order_id)
        return list(merged.values())


@dataclass
class CountSheet:
    bin: Bin
    expected: dict[str, int]
    counted: dict[str, int] = field(default_factory=dict)

    def enter(self, sku: str, qty: int) -> None:
        if qty < 0:
            raise ValueError("Zählmenge darf nicht negativ sein")
        self.counted[sku] = qty

    def complete(self) -> bool:
        return set(self.expected) <= set(self.counted)

    def differences(self) -> dict[str, int]:
        skus = set(self.expected) | set(self.counted)
        diff = {sku: self.counted.get(sku, 0) - self.expected.get(sku, 0) for sku in skus}
        return {sku: d for sku, d in sorted(diff.items()) if d}


class Stocktake:
    """Eine Zählrunde über einige Fächer.

    start() sperrt die Fächer; bis finish() kommissioniert niemand daraus (siehe
    Warehouse.primary_bin). finish() bucht die Differenzen und hebt die Sperre auf, auch
    wenn das Buchen scheitert.
    """

    def __init__(self, warehouse: Warehouse, bins: list[Bin]):
        if not bins:
            raise ValueError("Inventur ohne Fächer")
        self.warehouse = warehouse
        self.bins = sorted(set(bins))
        self.sheets: dict[Bin, CountSheet] = {}
        self.started = False
        self.finished = False

    def start(self) -> list[CountSheet]:
        if self.started:
            raise RuntimeError("Inventur läuft schon")
        snapshot = self.warehouse.snapshot()
        for bin_ in self.bins:
            expected = {sku: bins[bin_.label] for sku, bins in snapshot.items() if bin_.label in bins}
            self.sheets[bin_] = CountSheet(bin_, expected)
            self.warehouse.lock(bin_)
        self.started = True
        return list(self.sheets.values())

    def sheet(self, bin_: Bin) -> CountSheet:
        return self.sheets[bin_]

    def open_sheets(self) -> list[Bin]:
        return [b for b, s in self.sheets.items() if not s.complete()]

    def finish(self) -> dict[str, dict[str, int]]:
        if not self.started or self.finished:
            raise RuntimeError("Inventur nicht offen")
        if self.open_sheets():
            raise RuntimeError(f"nicht gezählt: {', '.join(b.label for b in self.open_sheets())}")
        booked: dict[str, dict[str, int]] = {}
        try:
            for bin_, sheet in self.sheets.items():
                diffs = sheet.differences()
                if not diffs:
                    continue
                self.warehouse.unlock(bin_)
                for sku, diff in diffs.items():
                    if diff > 0:
                        self.warehouse.put(sku, bin_, diff)
                    else:
                        self.warehouse.take(sku, bin_, -diff)
                booked[bin_.label] = diffs
        finally:
            for bin_ in self.bins:
                self.warehouse.unlock(bin_)
            self.finished = True
        return booked

