"""Aufteilung eines Auftrags auf Pakete."""

from __future__ import annotations

from lagerwerk.catalog import Catalog
from lagerwerk.config import MAX_PARCEL_WEIGHT_G
from lagerwerk.models import Article, Order, Parcel


class Unpackable(ValueError):
    """Ein einzelnes Stück passt in kein Paket."""


def fits(parcel: Parcel, extra_g: int) -> bool:
    return parcel.weight_g + extra_g < MAX_PARCEL_WEIGHT_G


def _pieces(order: Order, catalog: Catalog) -> list[Article]:
    pieces: list[Article] = []
    for line in order.lines:
        pieces.extend([catalog.get(line.sku)] * line.qty)
    return sorted(pieces, key=lambda article: (-article.weight_g, article.sku))


def split_into_parcels(order: Order, catalog: Catalog) -> list[Parcel]:
    """Verteilt die Stücke eines Auftrags auf möglichst wenige Pakete.

    Schwere Stücke zuerst (first fit decreasing). Gefahrgut bekommt eigene Pakete, damit
    der Rest des Auftrags unabhängig davon gebucht werden kann.
    """
    normal: list[Parcel] = []
    hazardous: list[Parcel] = []
    for article in _pieces(order, catalog):
        if not fits(Parcel(order.order_id, order.zone), article.weight_g):
            raise Unpackable(f"{article.sku} ({article.weight_g} g) passt in kein Paket")
        pool = hazardous if article.hazardous else normal
        for parcel in pool:
            if fits(parcel, article.weight_g):
                parcel.add(article.sku, 1, article.weight_g)
                break
        else:
            parcel = Parcel(order.order_id, order.zone)
            parcel.add(article.sku, 1, article.weight_g)
            pool.append(parcel)
    return normal + hazardous


def parcel_count(orders: list[Order], catalog: Catalog) -> int:
    """Wie viele Pakete ein Lauf ergibt; Aufträge, die nicht passen, zählen nicht."""
    total = 0
    for order in orders:
        try:
            total += len(split_into_parcels(order, catalog))
        except Unpackable:
            continue
    return total

