"""Zonentarif für den Sammelversand (Rahmenvertrag DPX 2025, Anlage 2)."""

from __future__ import annotations

from lagerwerk import money
from lagerwerk.models import Parcel

#: Preise je Zone und Gewichtsstufe (bis kg) aus der Preisliste des Vertrags.
ZONE_TABLE: dict[str, list[tuple[int, str]]] = {
    "DE": [(2, "4,10"), (5, "5,20"), (10, "6,90"), (31, "11,40")],
    "EU1": [(2, "9,50"), (5, "12,80"), (10, "16,20"), (31, "24,90")],
    "EU2": [(2, "12,90"), (5, "16,40"), (10, "21,00"), (31, "33,50")],
    "WORLD": [(2, "24,00"), (5, "36,50"), (10, "52,00"), (31, "89,00")],
}


class UnknownZone(KeyError):
    """Für die Zone gibt es keinen Tarif."""


class ZoneRateProvider:
    """Tarif nach Zone und Gewicht, optional mit festem Zuschlag je Paket (z. B. Maut)."""

    def __init__(self, table: dict[str, list[tuple[int, str]]] | None = None, surcharge: str = "0"):
        source = ZONE_TABLE if table is None else table
        self.table = {
            zone: [(limit_kg, money.cents_from_str(price)) for limit_kg, price in steps]
            for zone, steps in source.items()
        }
        self.surcharge_cents = money.cents_from_str(surcharge)

    def price_for(self, zone: str, weight_g: int) -> int:
        try:
            steps = self.table[zone]
        except KeyError:
            raise UnknownZone(zone) from None
        for limit_kg, cents in steps:
            if weight_g <= limit_kg * 1000:
                return cents
        return steps[-1][1]

    def quote(self, parcel: Parcel) -> int:
        return money.gross_cents(self.price_for(parcel.zone, parcel.weight_g) + self.surcharge_cents)

    def zones(self) -> list[str]:
        return sorted(self.table)
